-- MP-0016: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0016: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('syerleena-abdul-rashid','lim-hui-ying','rsn-rayer') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0016: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('bukit bendera','tanjong','jelutong') and slug not in ('syerleena-abdul-rashid','lim-hui-ying','rsn-rayer')) then raise exception 'MP-0016: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0016:%' and (m.source_type <> 'editorial' or e.slug not in ('syerleena-abdul-rashid','lim-hui-ying','rsn-rayer') or m.import_key not like 'MP-0016:' || e.slug || ':%')) then raise exception 'MP-0016: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'syerleena-abdul-rashid','Syerleena Abdul Rashid','government','Member of the Dewan Rakyat','Bukit Bendera','Pulau Pinang','Syerleena Abdul Rashid represents Bukit Bendera, Pulau Pinang, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4087','/portraits/syerleena-abdul-rashid.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P048.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4087"}, {"label": "DAP · representatives", "url": "https://dapmalaysia.org/pulau-pinang-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'lim-hui-ying','Lim Hui Ying','government','Deputy Minister of Women, Family and Community Development','Tanjong','Pulau Pinang','Lim Hui Ying represents Tanjong, Pulau Pinang, in the Dewan Rakyat. Current role: Deputy Minister of Women, Family and Community Development. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4088','/portraits/lim-hui-ying.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P049.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4088"}, {"label": "DAP · representatives", "url": "https://dapmalaysia.org/pulau-pinang-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'rsn-rayer','Sanisvara Nethaji Rayer','government','Member of the Dewan Rakyat','Jelutong','Pulau Pinang','Sanisvara Nethaji Rayer represents Jelutong, Pulau Pinang, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4089','/portraits/rsn-rayer.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P050.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4089"}, {"label": "DAP · representatives", "url": "https://dapmalaysia.org/pulau-pinang-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('syerleena-abdul-rashid','lim-hui-ying','rsn-rayer') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0016: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0016:syerleena-abdul-rashid:taman-air-itam-road','Resurface the road and renew parking markings at Block 1, Taman Air Itam','Infrastructure','achieved',null,null,null,null,'2026-09-19','https://www.buletinmutiara.com/ahli-parlimen-peruntuk-rm70855-naik-taraf-jalan-blok-1-taman-air-itam/','Syerleena’s constituency allocation funded the road and parking works, including markings for 35 parking spaces.','The delivery report states work ran from 20 April to 15 June 2026. Achieved covers only these completed works. No earlier public promise was established; September’s date is the evidence publication date.','2026-11-09','editorial',false from public.entities e where e.slug='syerleena-abdul-rashid' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.catego